using CK.Core;
using CK.Setup;
using System;
using System.Collections.Generic;
using System.Linq;

namespace CK.Cris.DynamicConfiguration;

/// <summary>
/// The run properties of the App (see <see cref="RunProperty"/>): generated by CK.Cris.DynamicConfiguration.Engine from
/// the types of the App that declare a <c>[ConfigurationSection]</c> and the restrictions of its configuration.
/// </summary>
[ContextBoundDelegation( "CK.Setup.RunPropertyDirectoryImpl, CK.Cris.DynamicConfiguration.Engine" )]
public abstract class RunPropertyDirectory : ISingletonAutoService
{
    Dictionary<string, RunProperty>? _byPath;

    /// <summary>
    /// Gets the run properties of the App, ordered by their path.
    /// </summary>
    public abstract IReadOnlyList<RunProperty> Properties { get; }

    /// <summary>
    /// Finds a run property by its path (case insensitive).
    /// </summary>
    /// <param name="path">The path.</param>
    /// <returns>The property or null.</returns>
    public RunProperty? Find( string path )
    {
        _byPath ??= Properties.ToDictionary( p => p.Path, StringComparer.OrdinalIgnoreCase );
        return _byPath.GetValueOrDefault( path );
    }
}
